import{_ as e,C as o,o as h,c as n,aj as d,E as r}from"./framework.js";const p=JSON.parse('{"title":"AI 悬浮助手 | Product | Documentation","description":"AI 悬浮助手 in Kooboo: AI 悬浮助手挂载在站点后台布局中。进入站点后台后，在右下角可以看到 AI 浮动按钮。","frontmatter":{"title":"AI 悬浮助手 | Product | Documentation","description":"AI 悬浮助手 in Kooboo: AI 悬浮助手挂载在站点后台布局中。进入站点后台后，在右下角可以看到 AI 浮动按钮。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/ai-floating-assistant.html"}]]},"headers":[],"relativePath":"zh/product/ai-floating-assistant.md","filePath":"product/ai-floating-assistant.md","lastUpdated":1786094386000}'),i={name:"zh/product/ai-floating-assistant.md"};function l(s,t,b,c,A,I){const a=o("DocImage");return h(),n("div",null,[t[0]||(t[0]=d('<h1 id="ai-悬浮助手" tabindex="-1">AI 悬浮助手 <a class="header-anchor" href="#ai-悬浮助手" aria-label="Permalink to &quot;AI 悬浮助手&quot;">​</a></h1><blockquote><p>站点后台右下角的全局 AI 浮窗，基于当前后台页面上下文提供建议、对话、工具调用和操作确认，并支持自由移动与缩放。</p></blockquote><h2 id="出现位置" tabindex="-1">出现位置 <a class="header-anchor" href="#出现位置" aria-label="Permalink to &quot;出现位置&quot;">​</a></h2><p>AI 悬浮助手挂载在站点后台布局中。进入站点后台后，在右下角可以看到 AI 浮动按钮。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>入口</td><td>右下角 <strong>AI</strong> 浮动按钮</td></tr><tr><td>层级</td><td>站点级上下文</td></tr><tr><td>常见页面</td><td>CMS 站点后台、开发菜单、开发者模式、站点级空白布局页面</td></tr><tr><td>不一定显示</td><td>控制台、市场、邮箱等账户级页面，或受限站点环境</td></tr></tbody></table><p>悬浮助手不会替代当前页面。它保留你正在操作的后台页面，在右下角打开一个可收起、可移动、可缩放的 AI 面板。</p>',6)),r(a,{src:"/product/ai-floating-assistant/floating-button.png",alt:"站点后台页面右下角的 AI 悬浮按钮",width:"1120"}),t[1]||(t[1]=d('<h2 id="上下文来源" tabindex="-1">上下文来源 <a class="header-anchor" href="#上下文来源" aria-label="Permalink to &quot;上下文来源&quot;">​</a></h2><p>悬浮助手打开时，会把当前站点和当前页面作为对话上下文的一部分。</p><table tabindex="0"><thead><tr><th>上下文</th><th>来源</th></tr></thead><tbody><tr><td>当前站点</td><td>URL 中的 <code>SiteId</code></td></tr><tr><td>当前页面</td><td>当前路由和路由标题，例如“页面”“内容”“站点设置”</td></tr><tr><td>会话历史</td><td>当前站点下的 AI 会话</td></tr><tr><td>当前资源引用</td><td>开发者模式或代码编辑器中手动添加的代码引用</td></tr><tr><td>可调用能力</td><td><a href="/kb-docs/zh/cms/settings/ai-service.html">CMS：AI 服务</a> 中启用的 MCP、AI 函数和内置工具</td></tr></tbody></table><p>面板顶部的 <strong>当前页面</strong> Banner 用来确认 AI 正在基于哪个后台页面理解问题。如果你从页面列表切到站点设置，再打开悬浮助手，Banner 也会随路由变化。</p><h2 id="展开和调整浮窗" tabindex="-1">展开和调整浮窗 <a class="header-anchor" href="#展开和调整浮窗" aria-label="Permalink to &quot;展开和调整浮窗&quot;">​</a></h2><p>点击右下角按钮后，浮窗会在当前页面上方展开。</p>',6)),r(a,{src:"/product/ai-floating-assistant/floating-panel.png",alt:"AI 悬浮助手展开状态：可移动和缩放的对话浮窗",width:"1120"}),t[2]||(t[2]=d('<table tabindex="0"><thead><tr><th>区域</th><th>怎么用</th></tr></thead><tbody><tr><td>标题栏</td><td>查看 Kooboo AI；拖动按钮之外的空白区域可以移动浮窗</td></tr><tr><td>当前页面 Banner</td><td>确认当前上下文来自哪个后台页面</td></tr><tr><td>消息区</td><td>查看 AI 回复、工具调用、思考过程、复制内容</td></tr><tr><td>输入区</td><td>输入问题，选择模型，上传图片，切换执行策略</td></tr><tr><td>发送按钮</td><td>点击发送，或使用 <code>Ctrl + Enter</code></td></tr></tbody></table><p>未展开时，如果当前页面有推荐操作，按钮上方可能显示“我可以”快捷建议。点击建议会直接打开面板并把对应操作带入当前会话。</p><h3 id="移动和缩放" tabindex="-1">移动和缩放 <a class="header-anchor" href="#移动和缩放" aria-label="Permalink to &quot;移动和缩放&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>方法</th></tr></thead><tbody><tr><td>移动浮窗</td><td>按住标题栏中不属于按钮、输入框或链接的空白区域拖动</td></tr><tr><td>调整宽度或高度</td><td>拖动浮窗任意一条边</td></tr><tr><td>同时调整宽高</td><td>拖动四个角；右下角和左下角会显示尺寸调整提示</td></tr><tr><td>临时放大</td><td>点击标题栏 <strong>全屏</strong>；按 <code>Esc</code> 或再次点击全屏按钮恢复</td></tr></tbody></table><p>浮窗最小尺寸为 <code>360 × 420</code> 像素，不能拖出可视区域，也不会越过后台顶部栏。浏览器窗口大小发生变化时，浮窗会自动收回可视范围。</p><p>浮窗的位置和尺寸保存在当前浏览器中。收起后再次打开，或刷新后台页面时，会恢复上次使用的浮窗布局；全屏状态不作为长期布局保存。</p><h2 id="标题栏按钮" tabindex="-1">标题栏按钮 <a class="header-anchor" href="#标题栏按钮" aria-label="Permalink to &quot;标题栏按钮&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td><strong>+</strong></td><td>新建会话</td></tr><tr><td>历史</td><td>打开最近会话，切回之前的对话</td></tr><tr><td>全屏</td><td>把浮窗扩展为全屏对话视图；适合阅读长回复或审阅修改</td></tr><tr><td>关闭</td><td>收起面板，回到右下角按钮</td></tr></tbody></table><h2 id="输入区" tabindex="-1">输入区 <a class="header-anchor" href="#输入区" aria-label="Permalink to &quot;输入区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td>模型选择</td><td>选择当前对话使用的 Provider 和模型；如果没有可选模型，先检查 <a href="./console/ai-config.html">控制台：AI 配置</a></td></tr><tr><td>执行策略</td><td>快捷切换 <strong>每次确认</strong>、<strong>仅自动执行允许项</strong>、<strong>自动执行</strong>；完整配置见 <a href="./ai-chat.html#设置">AI Claw 设置</a></td></tr><tr><td>上传图片</td><td>添加截图或图片作为上下文</td></tr><tr><td>Token 使用量</td><td>当界面显示使用量按钮时，可查看上下文窗口占用情况</td></tr><tr><td>发送 / 停止</td><td>未生成时发送消息，生成中则停止当前回答</td></tr></tbody></table><p>输入区支持编辑上一条用户消息、排队消息、停止后继续输入等交互。普通配置问题可以直接问；涉及写入、删除、代码修改或工具调用时，要先看清确认内容再执行。</p><h2 id="和开发者模式配合" tabindex="-1">和开发者模式配合 <a class="header-anchor" href="#和开发者模式配合" aria-label="Permalink to &quot;和开发者模式配合&quot;">​</a></h2><p>开发者模式中的资源标签和代码编辑器可以把当前文件加入 AI 对话引用。</p><table tabindex="0"><thead><tr><th>场景</th><th>操作</th></tr></thead><tbody><tr><td>解释当前代码</td><td>开发者模式打开资源 -&gt; 右键标签 -&gt; <strong>添加到对话</strong> -&gt; 打开悬浮助手提问</td></tr><tr><td>修改页面或脚本</td><td>先让 AI 说明修改思路 -&gt; 查看代码差异 -&gt; 确认后应用</td></tr><tr><td>排查 API 或 CodeBlock</td><td>在开发者模式调试资源 -&gt; 把代码加入引用 -&gt; 让 AI 基于代码上下文分析</td></tr></tbody></table><p>这里说明的是后台交互入口。KScript、模板资源和 API 的具体写法，请看 <a href="/kb-docs/zh/api/">API</a> 与 <a href="/kb-docs/zh/templateEngine/">模板引擎</a>。</p><h2 id="与-ai-claw-的区别" tabindex="-1">与 AI Claw 的区别 <a class="header-anchor" href="#与-ai-claw-的区别" aria-label="Permalink to &quot;与 AI Claw 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>AI 悬浮助手</th><th>AI Claw / AI Chat</th></tr></thead><tbody><tr><td>贴着当前后台页面使用</td><td>独立 AI 工作台：对话 + 左侧面板 + 右侧站点工作区</td></tr><tr><td>适合边配置边提问、快速解释当前页面</td><td>适合建站预览、看代码、跑固定任务、查任务日志和人工帮助</td></tr><tr><td>入口是右下角浮动按钮</td><td>入口是顶部 <strong>AI</strong> 按钮</td></tr></tbody></table><h2 id="常用工作流" tabindex="-1">常用工作流 <a class="header-anchor" href="#常用工作流" aria-label="Permalink to &quot;常用工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>操作</th></tr></thead><tbody><tr><td>问当前页面怎么配置</td><td>打开目标 CMS 页面 -&gt; 点击右下角 AI -&gt; 直接提问</td></tr><tr><td>让 AI 检查配置顺序</td><td>保持页面打开 -&gt; 在浮窗中描述目标 -&gt; 按回复检查字段</td></tr><tr><td>边看列表边对话</td><td>打开浮窗 -&gt; 拖到不遮挡列表的位置 -&gt; 从边缘调整合适尺寸</td></tr><tr><td>处理长回复</td><td>打开浮窗 -&gt; 点击全屏 -&gt; 阅读或复制内容；按 <code>Esc</code> 恢复</td></tr><tr><td>回到完整 AI 工作台</td><td>顶部 <strong>AI</strong> -&gt; 进入 <a href="./ai-chat.html">AI Claw / AI Chat</a></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./ai-chat.html">AI Claw / AI Chat</a></td><td>独立 AI 工作台：对话、预览、任务与设置</td></tr><tr><td><a href="./console/ai-config.html">控制台：AI 配置</a></td><td>组织级 AI Provider API Key</td></tr><tr><td><a href="/kb-docs/zh/cms/settings/ai-service.html">CMS：AI 服务</a></td><td>MCP 与 AI 函数配置</td></tr><tr><td><a href="./developer-mode.html">开发者模式</a></td><td>编辑、调试和添加代码引用</td></tr></tbody></table>',21))])}const _=e(i,[["render",l]]);export{p as __pageData,_ as default};
